import type { Dependency } from '../types';
export type FlatObject = {
    [key: string]: string;
};
export type PackageJson = {
    name: string | undefined;
    version: string;
    exports: any;
    dependencies: FlatObject;
};
export type RealPkgJson = {
    packageJson: any;
    path: string;
};
export type OutFile = {
    fileName: string;
    entryName?: string;
};
export type InputMap = {
    [key: string]: {
        entryTarget: string;
        originalMapping: string;
    };
};
export type DependencyOptions = {
    addDependency: (options: Dependency) => void;
    dependencyId: string | undefined;
    moduleRoot: string;
    cb: ({ moduleName }: {
        moduleName: string;
    }) => void;
};
export type HandlerFunction = (id: string, parentId: string | undefined, isResolved: boolean) => boolean;
